// The provider's webhook payloads carry the bank's own decline text; these are the ones worth a clear message.
var declines = []struct {
	re  *regexp.Regexp
	msg string
}{
	{regexp.MustCompile(`(?i)insufficient funds`), "the card was declined: insufficient funds"},
	{regexp.MustCompile(`(?i)authentication (failed|rejected)`), "the bank could not confirm it was you"},
	{regexp.MustCompile(`(?i)card (expired|not supported)`), "this card cannot be used; try another"},
}
